package com.astarworks.astera.core.application.config

import com.astarworks.astera.core.application.contents.SpriteDefinition
import com.astarworks.astera.core.domain.effect.vfx.SpriteId
import kotlinx.serialization.Serializable

/**
 * YAML-shaped DTO for `content/sprites/<id>.yaml` (generated by `:tools:item-art`, ADR-0239).
 *
 * ```yaml
 * id: spark
 * frames: 6
 * size: 32
 * ```
 */
@Serializable
public data class SpriteYamlConfig(
    public val id: String,
    public val frames: Int,
    public val size: Int = 32,
) {
    /** Throws [IllegalArgumentException] on an invalid id / range; the contents loader counts that as a failed load. */
    public fun toDefinition(): SpriteDefinition = SpriteDefinition(SpriteId(id), frames, size)
}
